############################################# ### Generated from PreTeXt source ### ### https://pretextbook.org ### ############################################# ## DBsubject() ## DBchapter() ## DBsection() ## Level() ## KEYWORDS() ## TitleText1() ## EditionText1() ## AuthorText1() ## Section1(not reported) ## Problem1(3.7.5.13) ## Author() ## Institution() ## Language(en-US)
DOCUMENT();
############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "PCCmacros.pl", "contextForm.pl", "contextFraction.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
($A, $B, $C) = random_subset(3, 20 .. 99); ($A, $B) = (random(0,1)) ? (-$A, $B) : ($A, -$B); Context("Fraction"); $x = Fraction($C/$A); $y = Fraction($C/$B); $m = Fraction(-$y/$x); Context()->variables->add(y => 'Real'); Context()->noreduce('(-x)-y', '(-x)+y'); $left = Formula("$A x + $B y")->reduce; $right = Formula("$C"); Context("Point"); $xi = Compute("($x,0)"); $yi = Compute("(0,$y)");
############################# # Exercise Group Introduction #############################
BEGIN_PGML Find both intercepts and the slope of the line.
END_PGML
###### # Body ######
BEGIN_PGML [`[$left]=[$right]`]
[@KeyboardInstructions('Enter the [`x`]-intercept here.')@]**
[_]{$xi}{5}
[@KeyboardInstructions('Enter the [`y`]-intercept here.')@]**
[_]{$yi}{5}
[@KeyboardInstructions('Enter the slope here.')@]**
[_]{$m}{5}
END_PGML
############# # End Problem #############
ENDDOCUMENT();
